import React from 'react';

const daysOfWeek = ['Lunes', 'Martes', 'Miércoles', 'Jueves', 'Viernes', 'Sábado', 'Domingo'];


const InformeSemanal = ({ reportData, formatCLP }) => {
  // Si no hay datos, muestra la estructura vacía pero visible
  const hasData = reportData && Object.keys(reportData).length > 0 && !reportData.error;

  return (
    <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
      <div>
        <h2 className="text-lg font-bold mb-4 text-indigo-700">Resumen semanal</h2>
        {/* Mostrar log de datos para depuración */}
        <pre className="bg-gray-100 text-xs p-2 mb-2 rounded text-gray-600">{JSON.stringify(reportData, null, 2)}</pre>
        {hasData ? (
          <ul className="space-y-2">
            <li>
              <span className="font-semibold">Total ventas:</span> {formatCLP(reportData.totalSales)}
            </li>
            <li>
              <span className="font-semibold">N° de ventas:</span> {reportData.salesCount}
            </li>
            <li>
              <span className="font-semibold">Ticket promedio:</span> {formatCLP(reportData.avgTicket)}
            </li>
          </ul>
        ) : (
          <div className="text-gray-400 py-12">No hay datos para la semana seleccionada o hubo un error.</div>
        )}
        {hasData && reportData.breakdownByPayment && (
          <div className="mt-6">
            <h3 className="font-semibold mb-2">Métodos de pago</h3>
            <ul className="space-y-1">
              {Object.entries(reportData.breakdownByPayment).map(([metodo, val]) => (
                <li key={metodo}>
                  <span className="capitalize">{metodo}:</span> {val.cantidad} ventas ({formatCLP(val.total)})
                </li>
              ))}
            </ul>
          </div>
        )}
      </div>
      <div>
        <h2 className="text-lg font-bold mb-4 text-indigo-700">Ventas por día</h2>
        <div className="overflow-x-auto">
          <table className="min-w-full text-sm">
            <thead>
              <tr className="bg-gray-100">
                {daysOfWeek.map(day => (
                  <th key={day} className="px-2 py-1 font-semibold">{day}</th>
                ))}
              </tr>
            </thead>
            <tbody>
              <tr>
                {(hasData && reportData.salesByDay ? reportData.salesByDay : Array(7).fill(0)).map((val, idx) => (
                  <td key={idx} className="px-2 py-1 text-center">{formatCLP(val)}</td>
                ))}
              </tr>
            </tbody>
          </table>
        </div>
        <div className="mt-8">
          <h3 className="font-semibold mb-2">Top productos vendidos</h3>
          {hasData && reportData.topProducts && reportData.topProducts.length > 0 ? (
            <ol className="list-decimal list-inside space-y-1">
              {reportData.topProducts.map((prod, idx) => (
                <li key={prod.name || idx}>
                  {prod.name} <span className="text-gray-500">({prod.sold} unds)</span>
                </li>
              ))}
            </ol>
          ) : (
            <div className="text-gray-400">No hay productos vendidos esta semana.</div>
          )}
        </div>
      </div>
    </div>
  );
};

export default InformeSemanal;
